// Parse Claude response into structured brief
const claudeResponse = $input.first().json;
const content = claudeResponse.body?.content?.[0]?.text ?? '{}';
let parsed;
try {
  parsed = JSON.parse(content);
} catch {
  parsed = { interpretation: content, error: 'Non-JSON response from Claude' };
}

const now = new Date().toISOString();
const briefId = 'brief_' + Math.random().toString(36).substring(2, 10);
const runId = 'run_' + Math.random().toString(36).substring(2, 10);

return [{
  json: {
    brief_id: briefId,
    run_id: runId,
    title: $('New Brief Webhook').first().json.body.title || `Mirror — ${now.split('T')[0]}`,
    artist_name: $('New Brief Webhook').first().json.body.artist_name,
    source_type: $('New Brief Webhook').first().json.body.source_type,
    source_text: $('New Brief Webhook').first().json.body.source_text,
    ...parsed,
    model_used: 'claude-opus-4-6',
    created_at: now,
    workflow: 'mirror-brief-create',
    status: 'completed'
  }
}];
